let wrapped = trimmed;
if (trimmed.length > this._maxLineChars) {
    const words = trimmed.split(" ");
    const lines: string[] = [];
    let current = "";
    for (const word of words) {
        if ((current + " " + word).trim().length > this._maxLineChars) {
            if (current) lines.push(current);
            current = word;
        } else {
            current = current ? current + " " + word : word;
        }
    }
    if (current) lines.push(current);
    wrapped = lines.join("\n");
}

export interface SubtitlesOptions {
    /** Preset design configuration. Overrides unset options with curated theme defaults. */
    preset?: "obsidian" | "pill" | "minimal" | "broadcast" | "neon" | "glass" | "light";

    /** Font size in Retiam world units. Defaults to 0.38. */
    fontSize?: number;

    /** Text color (Color instance or hex string). Defaults to #F8FAFC. */
    textColor?: Color | string;

    /** Text opacity [0.0 - 1.0]. Defaults to 1.0. */
    textOpacity?: number;

    /** Background pill fill color. Defaults to #060913. */
    backdropColor?: Color | string;

    /** Background pill fill opacity [0.0 - 1.0]. Defaults to 0.85. */
    backdropOpacity?: number;

    /** Stroke border color around backdrop pill. Defaults to translucent cyan/slate. */
    strokeColor?: Color | string;

    /** Stroke border width in world units. Defaults to 0.02. */
    strokeWidth?: number;

    /** Whether to render a stroke border around the backdrop pill. Defaults to true. */
    showBorder?: boolean;

    /**
     * Corner radius for the backdrop pill.
     * Uniform circular radius number, or [topLeft, topRight, bottomRight, bottomLeft].
     * Defaults to 0.22 world units.
     */
    cornerRadius?: number | [number, number, number, number];

    /**
     * Whether to format the backdrop pill as a full stadium pill (semicircular ends).
     * When true, cornerRadius is automatically computed as `height / 2`.
     * Defaults to false.
     */
    pillShape?: boolean;

    /** Whether to render a backdrop pill behind text. Defaults to true. */
    showBackdrop?: boolean;

    /** Inner padding [horizontal, vertical] or uniform number around text. Defaults to [0.55, 0.26]. */
    padding?: [number, number] | number;

    /** Maximum world-unit width before constraining line wrap. Defaults to 15.0. */
    maxWidth?: number;

    /** Maximum character count per line before automatic word-wrapping. Defaults to 65. */
    maxLineChars?: number;

    /** Multiplier for vertical line-height spacing on multi-line text. Defaults to 1.35. */
    lineHeight?: number;

    /** Bottom margin coordinate offset (Y position in scene). Defaults to -5.0. */
    bottomOffset?: number;

    /** Z-index depth for rendering on top of scene graphics. Defaults to 999. */
    zIndex?: number;
}

