import { Scene, hex } from "retiam";
import { Subtitles, speak } from "retiam/tts";

export class MathExplainerScene extends Scene {
    public async construct(): Promise<void> {
        // 1. Add Subtitles with Obsidian preset at bottom safe area
        const subtitles = new Subtitles({
            preset: "obsidian",
            fontSize: 0.38,
            bottomOffset: -5.0
        });
        this.add(subtitles);

        // 2. Speak narration synchronized with subtitles
        await speak(this, "The Stars and Bars theorem establishes a bijection between integer compositions and partitions.", {
            provider: "msedge",
            voice: "en-US-AndrewNeural",
            speed: 0.96,
            subtitles
        });
    }
}

